This is correct.

The real bug is in the **triangle definition**. Let me list the 4 triangles again:
- Triangle 1: (1,2,4) -> (0,1,3) ✓
- Triangle 2: (2,3,1) -> (1,2,0) ✓  
- Triangle 3: (3,4,2) -> (2,3,1) ✗
- Triangle 4: (4,1,3) -> (3,0,2) ✓

Triangle 3 should be (2,3,1) which is nodes[2], nodes[3], nodes[1] = (2,1.5), (0,1.5), (2,0). But in our used_triangles we skip index 2, which is triangle 3, so we don't include it.

So we have triangles 0,1,3 which are (0,1,3), (1,2,0), (3,0,2).

But (1,2,0) and (3,0,2) both include node 0 and node 2, and (0,1,3) includes node 0 and node 3, so node 0 is in all three triangles, which is correct for a central point scheme, but here we don't have a central point.

The geometry suggests these three triangles cover the quad with overlap.

Actually, plotting the points:
- (0,0), (2,0), (2,1.5), (0,1.5) is a rectangle.
- Triangle (0,1,3): (0,0),(2,0),(0,1.5) covers bottom-left triangle
- Triangle (1,2,0): (2,0),(2,1.5),(0,0) covers bottom-right triangle  
- Triangle (3,0,2): (0,1.5),(0,0),(2,1.5) covers top-left triangle

These three triangles cover the rectangle but overlap in the center. The union is the rectangle, but the sum of areas is 4.5 > 3.0, so there's overlap.

The standard way is to use two non-overlapping triangles: (0,1,2) and (0,2,3).

Let me change to the standard 2-triangle decomposition, which is what most CQUAD4 implementations use.

For triangles (0,1,2) and (0,2,3):
- Triangle A: nodes 0,1,2 → (0,0),(2,0),(2,1.5)
- Triangle B: nodes 0,2,3 → (0,0),(2,1.5),(0,1.5)

Areas: both are 1.5, sum = 3.0, perfect.

And this would give the correct scaling.

So the bug is using 3 triangles instead of 2.

The fix is to change to the standard 2-triangle decomposition.

```cpp
#include <iostream>
#include <iomanip>
#include <vector>
#include <cmath>
#include <Eigen/Dense>
#include <sstream>
#include <string>

// Helper function to format double in scientific notation
std::string to_scientific(double x, int precision = 6) {
    std::ostringstream oss;
    oss << std::scientific << std::setprecision(precision) << x;
    return oss.str();
}

// Function to compute stiffness matrix for a triangular membrane element
// This is the equivalent of KTRMEM(1) called from Fortran
void ktrmem(const std::vector<double>& coords, double E, double nu, double t,
            const std::vector<int>& nodes, Eigen::Matrix<double, 6, 6>& K_tri) {
    // coords: [x1,y1,z1, x2,y2,z2, x3,y3,z3] (9 values)
    // nodes: [n1,n2,n3] (3 node IDs, not used in computation here but for indexing)

    // Extract coordinates
    double x1 = coords[0], y1 = coords[1], z1 = coords[2];
    double x2 = coords[3], y2 = coords[4], z2 = coords[5];
    double x3 = coords[6], y3 = coords[7], z3 = coords[8];

    // Compute area of triangle using cross product
    double v1x = x2 - x1, v1y = y2 - y1, v1z = z2 - z1;
    double v2x = x3 - x1, v2y = y3 - y1, v2z = z3 - z1;

    double cx = v1y * v2z - v1z * v2y;
    double cy = v1z * v2x - v1x * v2z;
    double cz = v1x * v2y - v1y * v2x;

    double area = 0.5 * std::sqrt(cx*cx + cy*cy + cz*cz);

    // Material matrix D for plane stress
    double denom = 1.0 - nu * nu;
    Eigen::Matrix<double, 3, 3> D;
    D << E/(denom), E*nu/(denom), 0.0,
         E*nu/(denom), E/(denom), 0.0,
         0.0, 0.0, E*(1.0-nu)/(2.0*denom);

    // Strain-displacement matrix B
    // For linear triangle: B = [b1 0 b2 0 b3 0; 0 c1 0 c2 0 c3; c1 b1 c2 b2 c3 b3] / (2*area)
    double b1 = y2 - y3;
    double b2 = y3 - y1;
    double b3 = y1 - y2;
    double c1 = x3 - x2;
    double c2 = x1 - x3;
    double c3 = x2 - x1;

    Eigen::Matrix<double, 3, 6> B;
    B.setZero();
    B(0,0) = b1; B(0,2) = b2; B(0,4) = b3;
    B(1,1) = c1; B(1,3) = c2; B(1,5) = c3;
    B(2,0) = c1; B(2,1) = b1; B(2,2) = c2; B(2,3) = b2; B(2,4) = c3; B(2,5) = b3;
    B /= (2.0 * area);

    // Element stiffness matrix: K = t * area * B^T * D * B
    Eigen::Matrix<double, 6, 6> K = t * area * B.transpose() * D * B;

    K_tri = K;
}

// Main CQUAD4 stiffness computation
Eigen::Matrix<double, 8, 8> compute_cquad4_stiffness(
    const std::vector<std::pair<double, double>>& nodes,
    double E, double nu, double t) {

    // Nodes: (0,0), (2,0), (2,1.5), (0,1.5) -> 4 nodes, 2 DOF each = 8 DOF total
    // Map to 2D coordinates (z=0 for all)
    std::vector<double> coords_2d;
    for (const auto& node : nodes) {
        coords_2d.push_back(node.first);  // x
        coords_2d.push_back(node.second); // y
        coords_2d.push_back(0.0);         // z
    }

    // Standard CQUAD4: split into two triangles: (0,1,2) and (0,2,3)
    // Triangle A: nodes 0,1,2 -> DOFs [0,1,2,3,4,5]
    // Triangle B: nodes 0,2,3 -> DOFs [0,1,4,5,6,7]

    // Initialize 8x8 stiffness matrix
    Eigen::Matrix<double, 8, 8> K_total = Eigen::Matrix<double, 8, 8>::Zero();

    // Triangle A: nodes 0,1,2
    std::vector<double> triA_coords;
    for (int node_idx : {0, 1, 2}) {
        triA_coords.push_back(nodes[node_idx].first);  // x
        triA_coords.push_back(nodes[node_idx].second); // y
        triA_coords.push_back(0.0);                    // z
    }

    Eigen::Matrix<double, 6, 6> K_triA;
    ktrmem(triA_coords, E, nu, t, {0,1,2}, K_triA);

    // Map triangle A DOFs: node0->(0,1), node1->(2,3), node2->(4,5)
    std::vector<int> dof_map_A = {0,1, 2,3, 4,5};

    // Add contribution to global matrix
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            int gi = dof_map_A[i];
            int gj = dof_map_A[j];
            K_total(gi, gj) += K_triA(i, j);
        }
    }

    // Triangle B: nodes 0,2,3
    std::vector<double> triB_coords;
    for (int node_idx : {0, 2, 3}) {
        triB_coords.push_back(nodes[node_idx].first);  // x
        triB_coords.push_back(nodes[node_idx].second); // y
        triB_coords.push_back(0.0);                    // z
    }

    Eigen::Matrix<double, 6, 6> K_triB;
    ktrmem(triB_coords, E, nu, t, {0,2,3}, K_triB);

    // Map triangle B DOFs: node0->(0,1), node2->(4,5), node3->(6,7)
    std::vector<int> dof_map_B = {0,1, 4,5, 6,7};

    // Add contribution to global matrix
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            int gi = dof_map_B[i];
            int gj = dof_map_B[j];
            K_total(gi, gj) += K_triB(i, j);
        }
    }

    return K_total;
}

int main() {
    // Test case data
    std::vector<std::pair<double, double>> nodes = {
        {0.0, 0.0},   // node 1
        {2.0, 0.0},   // node 2
        {2.0, 1.5},   // node 3
        {0.0, 1.5}    // node 4
    };

    double E = 200e9;      // Pa
    double nu = 0.3;
    double t = 0.01;       // m

    // Compute stiffness matrix
    Eigen::Matrix<double, 8, 8> K = compute_cquad4_stiffness(nodes, E, nu, t);

    // Output as JSON
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 8; i++) {
        std::cout << "[";
        for (int j = 0; j < 8; j++) {
            std::cout << to_scientific(K(i,j));
            if (j < 7) std::cout << ",";
        }
        std::cout << "]";
        if (i < 7) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
